MINSTER_TARGET = "LINE1_MINSTER_PRODUCTION_SHIFT"
MINSTER_X = 0.115  # nudged right to center under the "MINSTER" text
MINSTER_Y = -0.035  # image crop removed most of the gap; this is now a small intentional buffer

# D&I has no line-level rollup timeseries per physical machine (only the
