# spaced across the D&I row); expect to fine-tune once seen live.
DI_MACHINE_CODES = ["DI11", "DI12", "DI14", "DI15", "DI17", "DI18"]
DI_COLUMN_X = [0.30, 0.42, 0.54, 0.66, 0.78, 0.90]
DI_ROW_Y = {"number": -0.002, "production": -0.05, "scrap": -0.115}  # scrap moved down -- at -0.09 it was only ~1-2px from touching the production box above it (both 30px tall, 0.04 gap barely exceeded their combined half-heights)
DI_NUMBER_BOX_WIDTH = 46
DI_NUMBER_BOX_HEIGHT = 28
# Producción/Merma can run up to 8 digits with thousands separators (e.g.
