ISPRAY_MACHINE_CODES = ["ISPRAY11", "ISPRAY12", "ISPRAY13", "ISPRAY14", "ISPRAY15"]
ISPRAY_COLUMN_X = [0.05, 0.15, 0.25, 0.35, 0.45]
ISPRAY_ROW_Y = {"number": 0.93, "production": 0.882}
ISPRAY_VALUE_BOX_WIDTH = 86
# The "ISPRAY" caption is no longer baked into PLANT_IMAGE_B64 (erased from
