ISPRAY_LABEL = {"text": "ISPRAY", "x": 0.25, "y": 0.99, "size": 18, "color": "#d6d6d6"}

# The image occupies data y:[0,1] (unchanged, native proportions). This
# extends the y-axis range below 0 to add a plain black margin underneath
